#![allow(dead_code)]
#[path="../handheld/src/streaming/protocol.rs"]mod protocol;
#[path="../handheld/src/streaming/local_feed.rs"]mod local_feed;
#[path="../handheld/src/streaming/local_assets.rs"]mod assets;
use local_feed::*;
#[derive(Default)]struct Fake {generation:u32,ready:bool,presented:bool,accepted:bool,fail:usize,calls:usize,events:Vec<&'static str>,bytes:Vec<u8>,length:u32,id:u32,committed:bool}
impl Fake{fn enter(&mut self,event:&'static str)->Result<(),&'static str>{self.calls+=1;self.events.push(event);if self.calls==self.fail{Err("fault")}else{Ok(())}}}
impl Sink for Fake{
 type Error=&'static str;
 fn current(&self,g:u32)->bool{g==self.generation}
 fn ready(&mut self)->Result<bool,Self::Error>{self.enter("ready")?;Ok(self.ready)}
 fn begin(&mut self,h:protocol::Header)->Result<(),Self::Error>{self.enter("begin")?;assert_eq!((h.width,h.height),(720,480));self.length=h.length;self.id=h.id;Ok(())}
 fn write(&mut self,b:&[u8])->Result<(),Self::Error>{self.enter("write")?;assert!(b.len()<=CHUNK&&!b.is_empty());self.bytes.extend_from_slice(b);Ok(())}
 fn commit(&mut self)->Result<(),Self::Error>{self.enter("commit")?;if !self.accepted{return Err("rejected")}assert_eq!(self.bytes.len(),self.length as usize);self.committed=true;Ok(())}
 fn presented(&mut self,id:u32)->Result<bool,Self::Error>{self.enter("present")?;assert!(self.committed);assert_eq!(id,self.id);Ok(self.presented)}
}
fn fake()->Fake{Fake{generation:7,ready:true,presented:true,accepted:true,..Default::default()}}
fn crc(b:&[u8])->u32{!protocol::crc_update(!0,b)}
fn finish(feed:&mut Feed,sink:&mut Fake)->Result<Progress,Error<&'static str>>{for now in 0..100{match feed.step(sink,now*1000){Ok(Progress::Presented)=>return Ok(Progress::Presented),Err(e)=>return Err(e),_=>{}}}panic!("unbounded")}
#[test]fn all_twenty_four_actual_assets_feed_exactly_with_crc_and_bounded_chunks(){let mut total=0;for(loop_id,asset)in assets::LOOPS.iter().enumerate(){assert_eq!(asset.frames.len(),8);for(index,frame)in asset.frames.iter().enumerate(){let id=(loop_id*8+index)as u32;let mut feed=Feed::new(frame.data,frame.crc,id,7,0).unwrap();let mut sink=fake();assert_eq!(finish(&mut feed,&mut sink),Ok(Progress::Presented));assert_eq!(sink.bytes,frame.data);assert_eq!(sink.events.iter().filter(|&&e|e=="commit").count(),1);assert_eq!(crc(frame.data),frame.crc);total+=frame.data.len();}}assert_eq!(total,537211);}
#[test]fn each_chunk_boundary_and_final_short_chunk_are_exact(){for size in [1,4095,4096,4097,8192,protocol::MAX_FRAME as usize]{let bytes=vec![42;size];let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=fake();assert_eq!(finish(&mut feed,&mut sink),Ok(Progress::Presented));assert_eq!(sink.bytes,bytes);assert_eq!(sink.events.iter().filter(|&&e|e=="write").count(),size.div_ceil(CHUNK));}}
#[test]fn cancellation_at_every_step_prevents_any_later_io_or_commit(){let bytes=vec![0;10000];for cancel_after in 0..8{let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{presented:false,..fake()};for n in 0..cancel_after{feed.step(&mut sink,n*1000).unwrap();}sink.generation=8;let before=sink.calls;assert_eq!(feed.step(&mut sink,10000),Err(Error::Cancelled));assert_eq!(sink.calls,before);assert_eq!(feed.step(&mut sink,11000),Err(Error::Cancelled));assert_eq!(sink.calls,before);}}
#[test]fn generation_wrap_and_source_switch_invalidate_old_frame(){let bytes=[4;100];let mut feed=Feed::new(&bytes,crc(&bytes),0,u32::MAX,0).unwrap();let mut sink=Fake{generation:0,..fake()};assert_eq!(feed.step(&mut sink,0),Err(Error::Cancelled));assert!(sink.events.is_empty());}
#[test]fn every_sink_fault_is_terminal_and_never_retried(){let bytes=vec![1;9000];for fail in 1..=7{let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{fail,..fake()};assert_eq!(finish(&mut feed,&mut sink),Err(Error::Sink("fault")),"call{fail}");let before=sink.calls;assert_eq!(feed.step(&mut sink,90000),Err(Error::Cancelled));assert_eq!(sink.calls,before);assert!(sink.events.iter().filter(|&&e|e=="commit").count()<=1);}}
#[test]fn crc_mismatch_rejects_before_commit_even_after_forwarding(){let bytes=[5;500];let mut feed=Feed::new(&bytes,crc(&bytes)^1,0,7,0).unwrap();let mut sink=fake();assert_eq!(finish(&mut feed,&mut sink),Err(Error::Integrity));assert!(!sink.events.contains(&"commit"));assert!(!sink.committed);}
#[test]fn ready_is_not_an_acceptance_or_presentation_receipt(){let bytes=[7;10];let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{ready:false,presented:false,..fake()};assert_eq!(feed.step(&mut sink,0),Ok(Progress::More));assert_eq!(sink.events,["ready"]);sink.ready=true;assert_eq!(feed.step(&mut sink,1),Ok(Progress::More));assert_eq!(feed.step(&mut sink,2),Ok(Progress::More));assert_eq!(feed.step(&mut sink,3),Ok(Progress::More));assert_eq!(feed.step(&mut sink,4),Ok(Progress::Committed));assert_eq!(feed.step(&mut sink,5),Ok(Progress::More));sink.presented=true;assert_eq!(feed.step(&mut sink,6),Ok(Progress::Presented));}
#[test]fn commit_rejection_or_post_commit_decoder_fault_is_not_presented(){let bytes=[7;10];let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{accepted:false,..fake()};assert_eq!(finish(&mut feed,&mut sink),Err(Error::Sink("rejected")));let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{fail:5,..fake()};assert_eq!(finish(&mut feed,&mut sink),Err(Error::Sink("fault")));assert!(sink.committed);}
#[test]fn readiness_and_presentation_timeout_bound_the_whole_frame(){let bytes=[8;10];let mut feed=Feed::new(&bytes,crc(&bytes),0,7,10).unwrap();let mut sink=Fake{ready:false,..fake()};feed.step(&mut sink,10).unwrap();assert_eq!(feed.step(&mut sink,500010),Err(Error::Timeout));assert!(!sink.events.contains(&"begin"));let mut feed=Feed::new(&bytes,crc(&bytes),0,7,0).unwrap();let mut sink=Fake{presented:false,..fake()};for now in 0..5{feed.step(&mut sink,now).unwrap();}assert_eq!(feed.step(&mut sink,500000),Err(Error::Timeout));assert_eq!(sink.events.iter().filter(|&&e|e=="commit").count(),1);}
#[test]fn empty_and_oversize_frames_reject_without_allocating_in_feed(){assert!(matches!(Feed::new(&[],0,0,0,0),Err(Error::Bounds)));let bytes=vec![0;protocol::MAX_FRAME as usize+1];assert!(matches!(Feed::new(&bytes,0,0,0,0),Err(Error::Bounds)));assert!(std::mem::size_of::<Feed>()<160);}
#[test]fn five_fps_pacing_never_catches_up_with_bursts(){assert_eq!(next_due(100,200),200100);assert_eq!(next_due(100,250000),250000);assert_eq!(next_due(u64::MAX-2,u64::MAX),u64::MAX);}
#[test]fn actual_adapter_completion_predicate_rejects_reused_id_without_counter_progress(){assert!(!completion_observed(10,20,10,20,0x80000000,0x80000000));assert!(!completion_observed(10,20,11,20,7,7));assert!(!completion_observed(10,20,10,21,7,7));assert!(completion_observed(10,20,11,21,7,7));}
#[test]fn actual_adapter_completion_predicate_requires_exact_single_frame_and_right_id(){assert!(!completion_observed(10,20,11,21,8,7));assert!(!completion_observed(10,20,12,21,7,7));assert!(!completion_observed(10,20,11,22,7,7));assert!(!completion_observed(10,20,12,22,7,7));assert!(completion_observed(0,0,1,1,0,0));}
#[test]fn actual_adapter_completion_predicate_handles_counter_wrap_independently(){assert!(completion_observed(u32::MAX,u32::MAX,0,0,0,0));assert!(completion_observed(u32::MAX,10,0,11,7,7));assert!(completion_observed(10,u32::MAX,11,0,7,7));assert!(!completion_observed(u32::MAX,u32::MAX,1,0,7,7));}
